package com.KickHistory;

import com.google.inject.Provides;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.FriendsChatManager;
import net.runelite.api.FriendsChatMember;
import net.runelite.api.events.FriendsChatChanged;
import net.runelite.api.events.FriendsChatMemberLeft;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.Text;
import okhttp3.*;

import java.awt.image.BufferedImage;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.LinkedList;
import java.util.List;

@Slf4j
@PluginDescriptor(
        name = "Kick History",
        description = "Logs names of players kicked from specific Friends Chats",
        tags = {"friends", "chat", "kick", "log"}
)
public class KickHistory extends Plugin
{
    @Inject
    private Client client;

    @Inject
    private OkHttpClient okHttpClient;

    @Inject
    private ClientToolbar clientToolbar;

    @Inject
    private KickHistoryConfig config;

    private KickHistoryPanel panel;
    private NavigationButton navButton;

    // Cached list of target FCs for performance
    private final List<String> targetFcs = new ArrayList<>();

    private static class PendingKick {
        String displayName;
        String standardName;
        long time;
        int world;

        PendingKick(String displayName, String standardName, long time, int world) {
            this.displayName = displayName;
            this.standardName = standardName;
            this.time = time;
            this.world = world;
        }
    }

    private final LinkedList<PendingKick> pendingKicks = new LinkedList<>();

    @Override
    protected void startUp() throws Exception
    {
        panel = injector.getInstance(KickHistoryPanel.class);
        final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");

        navButton = NavigationButton.builder()
                .tooltip("Kick History")
                .icon(icon)
                .priority(10)
                .panel(panel)
                .build();

        if (config.showSidePanel())
        {
            clientToolbar.addNavigation(navButton);
        }

        // Build the cached list on startup
        updateTargetFcs();
    }

    @Override
    protected void shutDown() throws Exception
    {
        clientToolbar.removeNavigation(navButton);
        pendingKicks.clear();
        targetFcs.clear();
    }

    // --- Helper to build the cached list once ---
    private void updateTargetFcs()
    {
        targetFcs.clear();
        String targetFcConfig = config.targetFcName();
        if (targetFcConfig != null && !targetFcConfig.trim().isEmpty())
        {
            for (String owner : targetFcConfig.split(","))
            {
                targetFcs.add(Text.standardize(owner.trim()));
            }
        }
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!event.getGroup().equals("kickhistory"))
        {
            return;
        }

        if (event.getKey().equals("showSidePanel"))
        {
            if (config.showSidePanel())
            {
                clientToolbar.addNavigation(navButton);
            }
            else
            {
                clientToolbar.removeNavigation(navButton);
            }
        }
        else if (event.getKey().equals("targetFcName"))
        {
            // Rebuild the cached list if the user edits the text box
            updateTargetFcs();
        }
    }

    // --- Highly optimized check using the cached list ---
    private boolean isInTargetFC()
    {
        if (targetFcs.isEmpty()) {
            return false;
        }

        FriendsChatManager fcManager = client.getFriendsChatManager();
        if (fcManager == null || fcManager.getOwner() == null) {
            return false;
        }

        String currentOwner = Text.standardize(fcManager.getOwner());
        return targetFcs.contains(currentOwner);
    }

    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked event)
    {
        String option = Text.removeTags(event.getMenuOption());
        String target = Text.removeTags(event.getMenuTarget());

        if (option.startsWith("Kick user") || option.startsWith("Kick") || option.equalsIgnoreCase("Exclude"))
        {
            if (!isInTargetFC()) {
                return;
            }

            if (target.contains("(")) {
                target = target.substring(0, target.indexOf("("));
            }

            String displayName = target.trim();
            String standardName = Text.standardize(displayName);

            if (displayName.isEmpty() || displayName.length() > 12) {
                return;
            }

            int world = getPlayerWorld(standardName);

            pendingKicks.add(new PendingKick(displayName, standardName, System.currentTimeMillis(), world));
            log.info("Registered FC kick target: " + displayName + " on world " + world);
        }
        else if (option.equalsIgnoreCase("Confirm kick"))
        {
            if (!pendingKicks.isEmpty() && isInTargetFC())
            {
                PendingKick lastKick = pendingKicks.getLast();
                lastKick.time = System.currentTimeMillis();
                log.info("Kick confirmed in dialog. Refreshing timer for: " + lastKick.displayName);
            }
        }
    }

    private int getPlayerWorld(String standardTargetName)
    {
        FriendsChatManager fcManager = client.getFriendsChatManager();
        if (fcManager != null) {
            for (FriendsChatMember member : fcManager.getMembers()) {
                if (Text.standardize(member.getName()).equals(standardTargetName)) {
                    return member.getWorld();
                }
            }
        }
        return -1;
    }

    @Subscribe
    public void onFriendsChatChanged(FriendsChatChanged event)
    {
        if (!pendingKicks.isEmpty())
        {
            log.info("FC state changed. Clearing {} stale kick(s) from memory.", pendingKicks.size());
            pendingKicks.clear();
        }
    }

    @Subscribe
    public void onFriendsChatMemberLeft(FriendsChatMemberLeft event)
    {
        if (!isInTargetFC()) {
            return;
        }

        String standardLeftName = Text.standardize(event.getMember().getName());

        Iterator<PendingKick> it = pendingKicks.iterator();
        while (it.hasNext())
        {
            PendingKick pk = it.next();

            if (System.currentTimeMillis() - pk.time > 30000) {
                it.remove();
                continue;
            }

            if (pk.standardName.equals(standardLeftName))
            {
                log.info("Kick confirmed via FC Leave for: " + pk.displayName);
                it.remove();

                SwingUtilities.invokeLater(() -> panel.addKick(pk.displayName));
                sendWebhook(pk.displayName, pk.world);

                break;
            }
        }
    }

    private void sendWebhook(String displayPlayer, int world)
    {
        if (!config.webhookEnabled() || config.webhookUrl() == null || config.webhookUrl().isEmpty())
        {
            return;
        }

        String adminName = "Unknown";
        if (client.getLocalPlayer() != null && client.getLocalPlayer().getName() != null) {
            adminName = client.getLocalPlayer().getName();
        }

        String fcOwner = "Unknown FC";
        FriendsChatManager fcManager = client.getFriendsChatManager();
        if (fcManager != null && fcManager.getOwner() != null) {
            fcOwner = Text.removeTags(fcManager.getOwner());
        }

        String worldText = world > 0 ? " (W" + world + ")" : "";

        String jsonPayload = String.format("{\"content\": \"**Kick Logged:** `%s`%s was kicked from `%s` by `%s`\"}",
                displayPlayer, worldText, fcOwner, adminName);

        Request request = new Request.Builder()
                .url(config.webhookUrl())
                .post(RequestBody.create(MediaType.parse("application/json; charset=utf-8"), jsonPayload))
                .build();

        okHttpClient.newCall(request).enqueue(new Callback() {
            @Override
            public void onFailure(Call call, IOException e) {
                log.warn("Error sending KickHistory webhook", e);
            }

            @Override
            public void onResponse(Call call, Response response) throws IOException {
                response.close();
            }
        });
    }

    @Provides
    KickHistoryConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(KickHistoryConfig.class);
    }
}

package com.KickHistory;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup("kickhistory")
public interface KickHistoryConfig extends Config
{
    enum TimeFormat {
        TWELVE_HOUR,
        TWENTY_FOUR_HOUR
    }

    enum DateFormat {
        NUMERIC,
        NAMED
    }

    @ConfigItem(
            keyName = "timeFormat",
            name = "Time Format",
            description = "Choose between 12-hour (7:12 PM) and 24-hour (19:12) formats.",
            position = 1
    )
    default TimeFormat timeFormat()
    {
        return TimeFormat.TWELVE_HOUR;
    }

    @ConfigItem(
            keyName = "dateFormat",
            name = "Date Format",
            description = "Choose between numeric (05/11/2026) or named (May 11th).",
            position = 2
    )
    default DateFormat dateFormat()
    {
        return DateFormat.NAMED;
    }

    @ConfigItem(
            keyName = "showSidePanel",
            name = "Show Side Panel Icon",
            description = "Toggle the side panel icon on or off. Note: Requires a plugin restart or toggle to update.",
            position = 3
    )
    default boolean showSidePanel()
    {
        return true;
    }

    @ConfigItem(
            keyName = "targetFcName",
            name = "Target FC Name",
            description = "The owner name(s) of the Friends Chat to monitor, separated by commas (e.g., 'zealgains, altaccount').",
            position = 4
    )
    default String targetFcName()
    {
        return "";
    }

    @ConfigItem(
            keyName = "webhookEnabled",
            name = "Enable Webhook",
            description = "Toggle sending Friends Chat kick logs to Discord.",
            position = 5
    )
    default boolean webhookEnabled()
    {
        return false;
    }

    @ConfigItem(
            keyName = "webhookUrl",
            name = "Webhook URL",
            description = "The Discord Webhook URL for the kick logs.",
            position = 6,
            secret = true
    )
    default String webhookUrl()
    {
        return "";
    }

    // =========================================================
    // SECTION: CLEAN NATIVE SETUP GUIDE
    // =========================================================
    @ConfigSection(
            name = "📋 Plugin Setup Guide",
            description = "Click to expand or collapse the setup instructions",
            position = 7
    )
    String setupSection = "setupSection";

    @ConfigItem(
            keyName = "displayGuideText",
            name = "<html><body width='175'>"
                    + "<font color='#A0A0A0' face='sans-serif' size='3'>"
                    + "1. Open a Discord text channel.<br>"
                    + "2. Edit Channel > Integrations > Webhooks.<br>"
                    + "3. Create a New Webhook, copy the URL, and paste it into the box above.<br>"
                    + "4. Enter the exact account name of the FC Owner (e.g. 'zealgains') into the Target FC Name box.<br>"
                    + "<hr color='#2A2A2A'>"
                    + "<i>Note:<br>The plugin will ignore all clicks if you are not currently inside the FC owned by the name(s) listed in the Target box.</i><br><br>"
                    + "<i>You can track multiple chats by separating names with a comma (e.g. 'zealgains, altaccount').</i><br><br>"
                    + "<i>This plugin will not track kicks done by others in FC only your own</i><br><br>"
                    + "</font></body></html>",
            description = "Step-by-step configuration verification checklist",
            position = 8,
            section = setupSection
    )
    default boolean displayGuideText() { return false; }
}

package com.KickHistory;

import net.runelite.client.ui.PluginPanel;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.datatransfer.StringSelection;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import javax.inject.Inject;

public class KickHistoryPanel extends PluginPanel
{
    private final JTextArea logArea = new JTextArea();
    private final KickHistoryConfig config;

    @Inject
    public KickHistoryPanel(KickHistoryConfig config)
    {
        super();
        this.config = config;

        setBorder(new EmptyBorder(10, 10, 10, 10));
        setLayout(new BorderLayout());

        JPanel topPanel = new JPanel();
        topPanel.setLayout(new BoxLayout(topPanel, BoxLayout.Y_AXIS));
        topPanel.setBorder(new EmptyBorder(0, 0, 10, 0));

        JLabel title = new JLabel("Kick History Log");
        title.setForeground(Color.WHITE);
        title.setAlignmentX(Component.CENTER_ALIGNMENT);

        JLabel subTitle = new JLabel("Date | Time | Target");
        subTitle.setForeground(Color.LIGHT_GRAY);
        subTitle.setAlignmentX(Component.CENTER_ALIGNMENT);

        topPanel.add(title);
        topPanel.add(Box.createRigidArea(new Dimension(0, 2)));
        topPanel.add(subTitle);

        add(topPanel, BorderLayout.NORTH);

        logArea.setEditable(false);
        logArea.setLineWrap(true);
        logArea.setWrapStyleWord(true);
        logArea.setBackground(new Color(40, 40, 40));
        logArea.setForeground(Color.WHITE);
        logArea.setMargin(new Insets(5, 5, 5, 5));

        JScrollPane scrollPane = new JScrollPane(logArea);
        add(scrollPane, BorderLayout.CENTER);

        JButton copyBtn = new JButton("Copy All");
        copyBtn.addActionListener(e -> {
            StringSelection stringSelection = new StringSelection(logArea.getText());
            Toolkit.getDefaultToolkit().getSystemClipboard().setContents(stringSelection, null);
        });

        JButton clearBtn = new JButton("Clear Log");
        clearBtn.addActionListener(e -> logArea.setText(""));

        JPanel buttonPanel = new JPanel(new GridLayout(1, 2, 5, 0));
        buttonPanel.add(copyBtn);
        buttonPanel.add(clearBtn);
        add(buttonPanel, BorderLayout.SOUTH);
    }

    public void addKick(String name)
    {
        LocalDateTime now = LocalDateTime.now();
        String dateStr = formatDate(now, config.dateFormat());
        String timeStr = formatTime(now, config.timeFormat());

        String entry = String.format("%s | %s\n%s\n\n", dateStr, timeStr, name);

        SwingUtilities.invokeLater(() -> {
            logArea.append(entry);

            if (logArea.getLineCount() > 500) {
                try {
                    int endOfFirstLine = logArea.getLineEndOffset(0);
                    logArea.replaceRange("", 0, endOfFirstLine);
                } catch (Exception ex) {
                    // Ignore UI threading errors on trim
                }
            }

            logArea.setCaretPosition(logArea.getDocument().getLength());
            revalidate();
            repaint();
        });
    }

    private String formatDate(LocalDateTime date, KickHistoryConfig.DateFormat format)
    {
        if (format == KickHistoryConfig.DateFormat.NUMERIC) {
            return date.format(DateTimeFormatter.ofPattern("MM/dd/yyyy"));
        } else {
            int day = date.getDayOfMonth();
            String suffix = getDaySuffix(day);
            return date.format(DateTimeFormatter.ofPattern("MMMM d")) + suffix;
        }
    }

    private String formatTime(LocalDateTime time, KickHistoryConfig.TimeFormat format)
    {
        if (format == KickHistoryConfig.TimeFormat.TWENTY_FOUR_HOUR) {
            return time.format(DateTimeFormatter.ofPattern("HH:mm"));
        } else {
            return time.format(DateTimeFormatter.ofPattern("h:mm a"));
        }
    }

    private String getDaySuffix(final int n)
    {
        if (n >= 11 && n <= 13) {
            return "th";
        }
        switch (n % 10) {
            case 1:  return "st";
            case 2:  return "nd";
            case 3:  return "rd";
            default: return "th";
        }
    }
}
